export const caseStatusV = pgView("case_status_v", {	sourceId: uuid("source_id"),
	status: text(),
}).with({"securityInvoker":true}).as(sql`SELECT id AS source_id, COALESCE(( SELECT t.treatment::text AS treatment FROM case_treatments t WHERE t.cited_source_id = s.id AND t.confirmed_at IS NOT NULL AND t.rejected_at IS NULL ORDER BY t.confirmed_at DESC LIMIT 1), 'not_verified'::text) AS status FROM sources s WHERE type = 'judgment'::source_type`);